@startuml
class City {
  +name : string
  +inhabitants : int
}
class Attraction {
  +name : string
  +address : string
}
class GuidedTour {
  +duration : int
  +number : int
}
class Discount {
  +amount : float
}
class Person {
  +name : string
}
class Visitor extends Person {}
class Guide extends Person {}

City "1" -- "*" Attraction : has
Attraction "1" -- "*" GuidedTour : offered for
GuidedTour "1" -- "1" Guide : requires
GuidedTour "1" -- "0..20" Visitor : can take part in
GuidedTour "1" -- "*" Discount : certain visitors may be granted
Visitor "1" -- "*" Discount : granted to
@enduml

